package net.civeira.phylax.feature.observe.observedembed.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class PanelUidVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property panel uid of observed embed ")
  void test_panel_uid_v_o_builder() {
    Assertions.assertFalse(PanelUidVO.nullValue().getPanelUid().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(PanelUidVO.tryFrom(null).getPanelUid().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", PanelUidVO.from("one").getPanelUid().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> PanelUidVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", PanelUidVO.from("one").toString());
  }
}
